#:property PublishAot=false
using System.Globalization;
using System.Net;
using System.Text;
using System.Text.Json;

// Offline engineering report. Evidence-derived text is HTML-encoded; no remote
// scripts, assets, fonts or services are needed to read the assessment.
if(args is not [var dataDirectory,var output] || !Directory.Exists(dataDirectory))
    throw new ArgumentException("Usage: <assessment evidence directory> <HTML output>");
if(!Directory.Exists(Path.GetDirectoryName(Path.GetFullPath(output))))throw new DirectoryNotFoundException("HTML parent missing");
using var candidate=Load("candidate.json");using var oracle=Load("oracle.json");
using var direct=Load("direct.json");using var activity=Load("activity.json");using var coverage=Load("helper-coverage.json");
var cases=candidate.RootElement.GetProperty("cases").EnumerateArray().ToArray();
var corpus=candidate.RootElement.GetProperty("corpus").EnumerateArray().ToArray();
var states=corpus.GroupBy(c=>c.GetProperty("result").GetProperty("Status").GetString()!).ToDictionary(g=>g.Key,g=>g.Count());
var numerical=cases.Where(c=>c.GetProperty("result").GetProperty("Status").GetString()=="executed").ToArray();
var numericPass=numerical.Count(c=>c.GetProperty("passed").GetBoolean());
var summaries=new StringBuilder();var bars=new StringBuilder();
var labels=new Dictionary<string,string>{{"parsed","Structurally accepted"},{"input_rejected","Rejected by candidate syntax layer"},{"encoding_rejected","Encoding rejected"},{"input_unavailable","Missing / oversized / excluded input"},{"timeout","3-second worker timeout"}};
foreach(var pair in states.OrderByDescending(p=>p.Value))
{
    var label=labels.GetValueOrDefault(pair.Key,pair.Key);var percent=100d*pair.Value/corpus.Length;
    bars.Append($"<div class='barrow'><span>{E(label)}</span><div class='track'><i style='width:{F(percent)}%'></i></div><strong>{pair.Value}</strong><small>{F(percent)}%</small></div>");
}
foreach(var c in cases)
{
    var executed=c.GetProperty("result").GetProperty("Status").GetString()=="executed";
    var pass=c.GetProperty("passed").GetBoolean();
    var details=executed?$"{c.GetProperty("result").GetProperty("Analyses").GetArrayLength()} analysis/analyses; named analytical checks":string.Join("; ",c.GetProperty("result").GetProperty("Diagnostics").EnumerateArray().Select(x=>x.GetString()));
    summaries.Append($"<tr><th>{E(c.GetProperty("id").GetString())}</th><td><span class='pill {(pass?"ok":"gap")}'>{(pass?(executed?"Within declared bounds":"Expected rejection"):"Disagreement retained")}</span></td><td>{E(details)}</td></tr>");
}
var coverageRows=new StringBuilder();
foreach(var metric in coverage.RootElement.GetProperty("metrics").EnumerateArray())
    coverageRows.Append($"<tr><td>{E(metric.GetProperty("file").GetString())}</td><td>{metric.GetProperty("covered_lines")}/{metric.GetProperty("lines")}</td><td>{metric.GetProperty("covered_branches")}/{metric.GetProperty("branches")}</td></tr>");
var engine=activity.RootElement.GetProperty("SpiceSharp");var parser=activity.RootElement.GetProperty("SpiceSharpParser");
var engineHead=engine.GetProperty("commits")[0];var parserHead=parser.GetProperty("commits")[0];
var rl=direct.RootElement.GetProperty("rl_current");
var diode=cases.Single(c=>c.GetProperty("id").GetString()=="diode").GetProperty("checks")[0];
var drift=100*Math.Abs(diode.GetProperty("actual").GetDouble()/diode.GetProperty("Value").GetDouble()-1);
var html=$$$"""
